using System.Collections.Generic;
using System.Linq;
using Exegesis.Shared;
using static Exegesis.Fx.CommonLayers;

namespace Exegesis.Fx
{
    /// <summary>
    /// ncho's FX layers written as code, in controller order. The slot_* and rcs_* layers
    /// that follow these are generated by the slot and RCS tools.
    /// </summary>
    public static class NchoAvatar
    {
        public static AvatarDefinition Define() => new AvatarDefinition(FxControllers.Ncho, Layers(), Parameters(), Expressions());

        private static IEnumerable<ParamSpec> Parameters() =>
            CommonParameters.BuiltIns()
                .Concat(CommonParameters.FaceTracking())
                .Concat(CommonParameters.Body())
                .Concat(new[]
                {
                    // Wing contact sensors (see WingDeployWithSensors).
                    ParamSpec.Bool("wing_sensor_lower"),
                    ParamSpec.Bool("wing_sensor_upper"),
                });

        private const string Anim = "Assets/_exegesis/ncho/ncho_anim";

        private static ExpressionsSpec Expressions()
        {
            var loadouts = new MenuSpec($"{Anim}/ncho_loadout_menu.asset")
                .Button("Bare", "loadout", 1f)
                .Button("Full RCS", "loadout", 2f)
                .Button("Hard-Cases", "loadout", 3f);

            var back = new MenuSpec($"{Anim}/ncho_back_menu.asset")
                .Toggle("Thruster Backpack", "back_slot", 1f)
                .Toggle("Arm Backpack", "back_slot", 2f);

            var thighs = new MenuSpec($"{Anim}/ncho_thigh_menu.asset")
                .Toggle("Hard-Cases", "thigh_slot", 1f)
                .Toggle("Thruster Packs", "thigh_slot", 2f);

            var equipment = new MenuSpec($"{Anim}/ncho_gear_menu.asset")
                .SubMenu("Loadouts", loadouts)
                .Toggle("Hip Pouches", "pouches")
                .Toggle("Hard-Case Mounts", "hard-case_mounts")
                .Toggle("Arm Hard-Cases", "arm_hard-cases")
                .SubMenu("Back", back)
                .SubMenu("Thighs", thighs)
                .Toggle("Wings", "wings_deployed");

            var main = new MenuSpec($"{Anim}/ncho_main_menu.asset", CommonExpressions.NchoParams)
                .SubMenu("Equipment", equipment, Icons.Equipment)
                .Toggle("RCS", "rcs")
                .SubMenu("Panels", CommonExpressions.NchoPanels(), Icons.Panels)
                .SubMenu("Config", CommonExpressions.Config(), Icons.Config)
                .SubMenu("Expression", CommonExpressions.Expression(), Icons.Expression);

            // Not on the main menu: ncho_verypoor_features.prefab installs it through VRCFury.
            var tail = new MenuSpec($"{Anim}/ncho_tail_menu.asset")
                .Toggle("Tail between Legs", "tail_state", 1f)
                .Toggle("Tail in Hand", "tail_state", 2f);

            return new ExpressionsSpec(CommonExpressions.NchoParams, CommonExpressions.Parameters(), main,
                                       new[] { tail });
        }

        private static IEnumerable<LayerSpec> Layers()
        {
            yield return Base();
            yield return Blink("[ncho]_blink", Clips.Ncho("[ncho]_blink"));
            yield return ToolHolstering();
            yield return GlyphsNeutral();
            yield return Blushie();
            yield return VentGlow(Clips.Ncho("ncho_heat_glow"));
            yield return HeatRadiation(HeatRates.Ncho);
            yield return TalkingHeatAdd(HeatRates.Ncho);
            yield return HeatIntegral();
            yield return ProxHeatAdd(HeatRates.Ncho);
            yield return EvilHeatAdd(HeatRates.Ncho);
            yield return EyesNeutral(Clips.Ncho("[ncho]_eyes_neutral"));
            yield return Eyes();
            yield return OverlayOpen();
            yield return BattControl();
            yield return BattIndicator();
            yield return WaterLevel();
            yield return Ears();
            yield return TailState();
            yield return PanelsNeutral(Clips.Ncho("[panels]_neutral"));
            yield return PropsNeutral();
            yield return FaceOff();
            yield return ChestOff();
            yield return AbdomenOff();
            yield return GroinOff();
            yield return LeftArmOff();
            yield return RightArmOff();
            yield return LeftThighOff();
            yield return RightThighOff();
            yield return Pouches();
            yield return HardCaseMounts();
            yield return ArmHardCases();
            yield return WingDeployWithSensors();
            yield return PanelToolControl();
            yield return VertexRounding();
            yield return Audiolink();
            yield return FloorCollider();
            yield return Hud();
            yield return Transponder();
            yield return TouchNeutral();
            foreach (var t in Touches()) yield return t;
            yield return Eyeshadow();
        }
    }
}
